        ('mth11a-07-mcq-0010', 7, 'Evaluate lim(r→2) [(13/3)πr²].', '39π', '52/3π', '26/3π', '25/13π', 'b', 1, 'Use direct substitution because the expression is defined at the approach value.', 'Substitute r=2: (13/3)π(2)² = 52/3π. Option A: substituted 3 instead of 2. Option C: used r instead of r². Option D: inverted the coefficient 13/3 and shifted the result by one.'),
        ('mth11a-07-mcq-0011', 7, 'Evaluate lim(y→3) [(y² − 2)(y + 3)].', '42', '6', '21', '66', 'a', 1, 'Evaluate each factor at the approach value and multiply the two limits.', 'Substitute y=3: [(3)²−2](3+3) = (7)(6) = 42. Option B: used y instead of y² in the first factor. Option C: omitted the second occurrence of y. Option D: changed −2 to +2.'),
        ('mth11a-07-mcq-0012', 7, 'Evaluate lim(y→4) [(y² − 3)(y + 4)].', '152', '52', '8', '104', 'd', 2, 'Evaluate each factor at the approach value and multiply the two limits.', 'Substitute y=4: [(4)²−3](4+4) = (13)(8) = 104. Option A: changed −3 to +3. Option B: omitted the second occurrence of y. Option C: used y instead of y² in the first factor.'),
