        ('mth11a-07-mcq-0016', 7, 'Evaluate lim(y→4) [(y² − 7)(y + 4)].', '184', '36', '-24', '72', 'd', 1, 'Evaluate each factor at the approach value and multiply the two limits.', 'Substitute y=4: [(4)²−7](4+4) = (9)(8) = 72. Option A: changed −7 to +7. Option B: omitted the second occurrence of y. Option C: used y instead of y² in the first factor.'),
        ('mth11a-07-mcq-0017', 7, 'Evaluate lim(y→2) [(y² − 8)(y + 2)].', '-8', '-16', '-24', '48', 'b', 1, 'Evaluate each factor at the approach value and multiply the two limits.', 'Substitute y=2: [(2)²−8](2+2) = (-4)(4) = -16. Option A: omitted the second occurrence of y. Option C: used y instead of y² in the first factor. Option D: changed −8 to +8.'),
